import test from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync, writeFileSync, mkdirSync, mkdtempSync, rmSync, cpSync, existsSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { tmpdir } from 'node:os';
import { deflateSync, inflateSync } from 'node:zlib';
import { createHash } from 'node:crypto';
import { execFileSync } from 'node:child_process';
import { bytesDigest, digest } from '../../tools/drift/contracts.mjs';
import { FLOW_EQUIVALENCE_SOURCE as PIN } from '../../tools/drift/flow-equivalence.mjs';
import { assessRepair } from '../../tools/drift/repairability.mjs';
import { createFlowEquivalenceProof, loadFlowEquivalenceProof, revalidateFlowEquivalenceProof,
  verifyFlowEquivalenceAssets } from '../../tools/drift/flow-equivalence-assets.mjs';

// Actual pinned Git commit, required ancestor trees and six full blobs, compressed as raw object
// snapshots. A fresh tiny bare mirror is built entirely offline: tests exercise REAL git show,
// not a mocked subprocess, user checkout, shared cache, or network. Alternate deployments below
// are real new Git commit objects retaining these complete reviewed source snapshots.
const OBJECTS = '';
const OLD = 'https://app.hadrius.com/account', CURRENT = 'https://app.hadrius.com/settings/account';
function png(value) {
  const chunk = (type, data) => {
    const body = Buffer.concat([Buffer.from(type), data]); let crc = 0xffffffff;
    for (const byte of body) { crc ^= byte; for (let n = 0; n < 8; n++) crc = crc & 1 ? (crc >>> 1) ^ 0xedb88320 : crc >>> 1; }
    const size = Buffer.alloc(4), check = Buffer.alloc(4); size.writeUInt32BE(data.length); check.writeUInt32BE((crc ^ 0xffffffff) >>> 0);
    return Buffer.concat([size, body, check]);
  };
  const header = Buffer.alloc(13); header.writeUInt32BE(2, 0); header.writeUInt32BE(2, 4); header[8] = 8; header[9] = 2;
  return Buffer.concat([Buffer.from('89504e470d0a1a0a', 'hex'), chunk('IHDR', header),
    chunk('IDAT', deflateSync(Buffer.from([0, ...Array(6).fill(value), 0, ...Array(6).fill(value)]))), chunk('IEND', Buffer.alloc(0))]);
}
function fixture(t) {
  const root = mkdtempSync(join(process.env.TMPDIR || tmpdir(), 'flow-assets-test-'));
  t.after(() => rmSync(root, { recursive: true, force: true }));
  const mirror = join(root, 'frontend.git'), capture = join(root, 'capture');
  mkdirSync(capture);
  execFileSync('git', ['init', '--bare', '--quiet', mirror]);
  const objects = JSON.parse(inflateSync(Buffer.from(OBJECTS, 'base64')));
  for (const [sha, base64] of Object.entries(objects)) {
    const bytes = Buffer.from(base64, 'base64');
    assert.equal(createHash('sha1').update(bytes).digest('hex'), sha);
    const path = join(mirror, 'objects', sha.slice(0, 2), sha.slice(2));
    mkdirSync(dirname(path), { recursive: true }); writeFileSync(path, deflateSync(bytes));
  }
  const scriptPath = join(root, 'script.json'), jobPath = join(root, 'job.json'), runPath = join(capture, 'run.json');
  const prePath = join(capture, 'step-06-today.png'), postPath = join(capture, 'step-07-today.png');
  const target = { i: 30, name: 'Use as admin', role: 'button', tag: 'button', visible: true,
    inForm: false, inDialog: false, bbox: { x: 0, y: 0, w: 1, h: 1 } };
  const script = { name: 'Switching', recording: { id: 'recording-id' }, steps: [
    { index: 6, action: 'click', capture: true, target: { name: 'Use as admin', role: 'button' }, url: OLD, route: '/account', media: { pre: 'recorded-6.png' }, narration: 'Use as admin.' },
    { index: 7, action: 'navigate', capture: true, value: OLD, url: OLD, route: '/account', media: { pre: 'recorded-7.png' } },
  ] };
  const run = { script: script.name, recordingId: script.recording.id, scriptPath, status: 'captured',
    signedIn: true, tenantVerified: true, viewport: { width: 2, height: 2 }, findings: [
      { step: 3, kind: 'target_missing' }, // Not silently resolved; checker scopes only this click + next capture.
      { step: 6, kind: 'click_navigated_unexpectedly', expected: OLD, actual: CURRENT }], steps: [
      { index: 6, action: 'click', url: OLD, route: '/account', recordedMedia: 'recorded-6.png', screenshot: 'step-06-today.png',
        todayUrl: CURRENT, mutation: { mutating: false }, visibleText: 'Account\nUse as admin\nSign out',
        target: { status: 'resolved', method: 'name_any_role', recordedName: 'Use as admin', matches: [target], resolved: target, rect: target.bbox },
        clicked: true, performed: 'click', afterClickUrl: CURRENT },
      { index: 7, action: 'navigate', url: OLD, route: '/account', recordedMedia: 'recorded-7.png', screenshot: 'step-07-today.png',
        todayUrl: CURRENT, mutation: { mutating: false }, visibleText: 'People directory\nUse as employee\nSign out' },
    ] };
  const release = { currentSha: PIN.commit, routePath: '/settings/account', routeEntryFile: PIN.files[1].path, capturedAt: 'saved-run' };
  const job = { name: script.name, recordingId: script.recording.id, scriptPath, scriptHash: digest(script),
    captureStatus: 'captured', startedAt: 'saved-run', errors: [], evidence: { runDir: capture }, steps: [
      { index: 6, action: 'click', verdict: 'full_rerecord', target: { status: 'resolved', method: 'name_any_role', recordedName: 'Use as admin', todayName: 'Use as admin' },
        reasons: [{ code: 'flow_changed' }, { code: 'page_redesigned' }, { code: 'narration_unchecked' }], evidence: { today: prePath }, uiReleaseEvidence: release },
      { index: 7, action: 'navigate', evidence: { today: postPath }, uiReleaseEvidence: release },
    ] };
  const save = () => { for (const [path, value] of [[scriptPath, script], [jobPath, job], [runPath, run]]) writeFileSync(path, JSON.stringify(value)); };
  save(); writeFileSync(prePath, png(240)); writeFileSync(postPath, png(32));
  const options = { jobPath, stepIndex: 6, frontendGitDir: mirror };
  return { root, mirror, scriptPath, jobPath, runPath, prePath, postPath, script, run, job, save, options,
    create: () => createFlowEquivalenceProof(options), context: () => ({ step: job.steps[0], scriptStep: script.steps[0], name: script.name, frontendGitDir: mirror }) };
}

// Real unrelated root commit: its tree changes outside the reviewed paths, with NO ancestry
// to PIN. Rebuild only the path's trees, retaining all complete existing snapshot objects.
function deployment(f, path = 'unrelated-deployment.txt', bytes = 'unrelated deployment') {
  const git = (args, input) => execFileSync('git', ['--git-dir', f.mirror, ...args], { input, encoding: 'utf8' }).trim();
  const blob = git(['hash-object', '-w', '--stdin'], bytes);
  const replace = (tree, parts) => {
    const entries = git(['ls-tree', '-z', tree]).split('\0').filter(Boolean).map(x => {
      const [head, name] = x.split('\t'), [mode, type, sha] = head.split(' '); return { mode, type, sha, name };
    });
    const name = parts[0], old = entries.find(x => x.name === name);
    const entry = parts.length === 1 ? { mode: '100644', type: 'blob', sha: blob, name }
      : { ...old, sha: replace(old.sha, parts.slice(1)) };
    const next = entries.filter(x => x.name !== name).concat(entry);
    return git(['mktree', '-z', '--missing'], next.map(x => `${x.mode} ${x.type} ${x.sha}\t${x.name}\0`).join(''));
  };
  const tree = replace(git(['cat-file', '-p', PIN.commit]).split('\n')[0].slice('tree '.length), path.split('/'));
  const commit = `tree ${tree}\nauthor Offline Fixture <fixture@example.test> 1793653200 +0000\ncommitter Offline Fixture <fixture@example.test> 1793653200 +0000\n\nUnrelated deployment\n`;
  return git(['hash-object', '-t', 'commit', '-w', '--stdin'], commit);
}
function captureAt(f, commit) {
  f.options.captureCommit = commit;
  f.run.currentSha = commit; f.job.releaseEvidence = { currentSha: commit };
  for (const step of f.job.steps) step.uiReleaseEvidence.currentSha = commit;
  f.save();
}

test('unrelated exact deployment with same six blobs persists and revalidates without ancestry assumptions', t => {
  const f = fixture(t), actual = deployment(f); captureAt(f, actual);
  const third = deployment(f, 'unrelated-deployment.txt', 'third deployment');
  assert.notEqual(actual, PIN.commit);
  assert.doesNotMatch(execFileSync('git', ['--git-dir', f.mirror, 'cat-file', '-p', actual], { encoding: 'utf8' }), /^parent /m);
  // Static review pins suffice: reads must use the actual capture tree even if the historical
  // review commit itself is unavailable in this partial offline mirror.
  rmSync(join(f.mirror, 'objects', PIN.commit.slice(0, 2), PIN.commit.slice(2)));
  const proof = f.create();
  assert.equal(proof.verified, true, JSON.stringify(proof.reasons));
  assert.equal(proof.binding.source.captureCommit, actual);
  assert.equal(proof.binding.source.reviewedAtCommit, PIN.commit);
  assert.ok(proof.binding.source.files.every(x => x.gitObject === `${actual}:${x.path}`));
  const path = join(f.root, 'later-proof.json'); writeFileSync(path, JSON.stringify(proof));
  assert.deepEqual(loadFlowEquivalenceProof(path, f.context()), proof);
  assert.equal(verifyFlowEquivalenceAssets({ ...f.job.steps[0], flowEquivalence: proof }, f.context()), true);
  // A coherent-looking source claim cannot be transplanted back to PIN or another real commit.
  for (const commit of [PIN.commit, third]) {
    const forged = structuredClone(proof);
    forged.binding.source.commit = forged.binding.source.captureCommit = commit;
    for (const file of forged.binding.source.files) file.gitObject = `${commit}:${file.path}`;
    forged.bindingDigest = digest(forged.binding);
    assert.throws(() => revalidateFlowEquivalenceProof(forged, f.context()));
  }
  // Deleting actual commit cannot fall back to the reviewed commit's still-present blobs.
  rmSync(join(f.mirror, 'objects', actual.slice(0, 2), actual.slice(2)));
  assert.throws(() => loadFlowEquivalenceProof(path, f.context()), /source_(unavailable|commit_unavailable)/);
});

test('any reviewed source change at actual capture commit fails closed despite unchanged alias excerpt', async t => {
  for (const pin of PIN.files) await t.test(pin.path, t => {
    const f = fixture(t), bytes = execFileSync('git', ['--git-dir', f.mirror, 'show', `${PIN.commit}:${pin.path}`]);
    const actual = deployment(f, pin.path, Buffer.concat([bytes, Buffer.from('\n// changed reviewed implementation\n')]));
    captureAt(f, actual);
    const proof = f.create(); assert.equal(proof.verified, false); assert.ok(proof.reasons.includes('source_hash_mismatch'));
  });
});

test('explicit wrong or nonliteral capture SHA never resolves source from another commit', t => {
  const f = fixture(t), actual = deployment(f); captureAt(f, actual);
  f.options.captureCommit = PIN.commit;
  assert.equal(f.create().verified, false);
  for (const value of ['HEAD', `${actual}~0`, actual.toUpperCase(), `${actual}\n`, null]) {
    f.options.captureCommit = value;
    assert.throws(() => f.create(), /capture_commit_required/);
  }
});

test('legacy exact-PIN proof remains readable without rewriting its binding or artifact', t => {
  const f = fixture(t), proof = f.create();
  delete proof.binding.source.reviewedAtCommit; delete proof.binding.source.captureCommit;
  proof.bindingDigest = digest(proof.binding);
  const path = join(f.root, 'legacy.json'); writeFileSync(path, JSON.stringify(proof));
  const before = readFileSync(path);
  assert.deepEqual(loadFlowEquivalenceProof(path, f.context()), proof);
  assert.deepEqual(readFileSync(path), before);
});

test('real offline git-show proof, persisted reload, bound assessment, and finalization gate preserve raw inputs', t => {
  const f = fixture(t), paths = [f.jobPath, f.runPath, f.scriptPath, f.prePath, f.postPath];
  const before = paths.map(p => bytesDigest(readFileSync(p))), proof = f.create();
  assert.equal(proof.verified, true, JSON.stringify(proof.reasons));
  assert.equal(proof.binding.source.commit, PIN.commit); assert.equal(proof.binding.source.files.length, 6);
  const artifact = join(f.root, 'proof.json'); writeFileSync(artifact, JSON.stringify(proof));
  assert.deepEqual(loadFlowEquivalenceProof(artifact, f.context()), proof);
  const st = { ...f.job.steps[0], flowEquivalence: proof };
  assert.equal(verifyFlowEquivalenceAssets(st, { scriptStep: f.script.steps[0], name: f.script.name, frontendGitDir: f.mirror }), true);
  const assessment = assessRepair({ name: f.script.name, steps: [st], scriptSteps: [f.script.steps[0]], slides: [{ index: 6, changes: [] }] });
  assert.deepEqual(assessment.blockers.map(b => b.code), ['large_redesign', 'narration_unchecked']);
  assert.ok(assessment.notes.some(n => n.code === 'flow_equivalence_verified'));
  assert.deepEqual(st.reasons, f.job.steps[0].reasons);
  assert.deepEqual(paths.map(p => bytesDigest(readFileSync(p))), before);
});

test('rereads EVERY bound JSON/image file: byte-stale content, even semantically identical JSON, fails', async t => {
  for (const key of ['jobPath', 'scriptPath', 'runPath', 'prePath', 'postPath']) await t.test(key, t => {
    const f = fixture(t), proof = f.create();
    writeFileSync(f[key], Buffer.concat([readFileSync(f[key]), Buffer.from('\n')]));
    assert.throws(() => revalidateFlowEquivalenceProof(proof, { frontendGitDir: f.mirror }), /flow_equivalence_stale_binding/);
  });
});

test('post-state must be observed in saved run, not detached proof claims or changed source metadata', async t => {
  for (const [label, mutate, reason] of [
    ['post-state', f => { f.run.steps[1].visibleText = 'Account\nUse as admin'; }, 'mode_postcondition_unverified'],
    ['script', f => { f.script.steps[0].target.name = 'Wrong'; }, 'identity_mismatch'],
    ['job identity', f => { f.job.name = 'Another video'; }, 'identity_mismatch'],
    ['wrong commit', f => { f.options.captureCommit = PIN.commit; f.job.steps[0].uiReleaseEvidence.currentSha = '0'.repeat(40); }, 'release_source_mismatch'],
    ['wrong step', f => { f.options.stepIndex = 7; }, 'flow_equivalence_step_not_unique'],
    ['wrong target', f => { f.run.steps[0].target.method = 'css'; }, 'target_not_unique_exact'],
    ['guard', f => { f.run.steps[0].prerequisiteUnverified = true; }, 'action_or_prerequisite_unverified'],
  ]) await t.test(label, t => {
    const f = fixture(t); mutate(f); f.save();
    if (label === 'wrong step') assert.throws(f.create, new RegExp(reason));
    else { const result = f.create(); assert.equal(result.verified, false); assert.ok(result.reasons.includes(reason), JSON.stringify(result)); }
  });
});

test('wrong/missing pinned Git blobs fail offline; replacement refs never authorize source', async t => {
  for (const type of ['missing', 'wrong bytes', 'replacement refs', 'lazy fetch', 'wrong mirror']) await t.test(type, t => {
    const f = fixture(t), proof = f.create(), pin = PIN.files[0];
    const objectPath = join(f.mirror, 'objects', pin.blobSha.slice(0, 2), pin.blobSha.slice(2));
    if (type === 'missing') rmSync(objectPath);
    if (type === 'wrong bytes') {
      const bytes = Buffer.from('source altered'); writeFileSync(objectPath, deflateSync(Buffer.concat([Buffer.from(`blob ${bytes.length}\0`), bytes])));
    }
    if (type === 'replacement refs') {
      const wrong = execFileSync('git', ['--git-dir', f.mirror, 'hash-object', '-w', '--stdin'], { input: 'wrong source', encoding: 'utf8' }).trim();
      mkdirSync(join(f.mirror, 'refs', 'replace'), { recursive: true }); writeFileSync(join(f.mirror, 'refs', 'replace', pin.blobSha), `${wrong}\n`);
      // Removing the real blob and substituting a replace ref must NOT satisfy a git-show read.
      rmSync(objectPath);
    }
    if (type === 'lazy fetch') {
      // A real local promisor remote contains the missing bytes and explicitly permits file
      // transport. Offline validation must still refuse, not fetch or repair the mirror.
      const remote = join(f.root, 'promisor.git'); cpSync(f.mirror, remote, { recursive: true });
      for (const [key, value] of [['remote.origin.url', remote], ['remote.origin.promisor', 'true'],
        ['extensions.partialclone', 'origin'], ['protocol.file.allow', 'always']]) {
        execFileSync('git', ['--git-dir', f.mirror, 'config', key, value]);
      }
      rmSync(objectPath);
    }
    const frontendGitDir = type === 'wrong mirror' ? join(f.root, 'absent.git') : f.mirror;
    assert.throws(() => revalidateFlowEquivalenceProof(proof, { frontendGitDir }), /flow_equivalence_(source_(commit_)?unavailable|recheck_failed:source_hash_mismatch)/);
    if (type === 'lazy fetch') assert.equal(existsSync(objectPath), false, 'no fetched object may be written');
  });
});

test('reload requires coherent binding AND fresh caller step/script/name; saved verified flag is insufficient', t => {
  const f = fixture(t), proof = f.create(), context = f.context();
  for (const mutate of [
    x => { x.verified = false; }, x => { x.bindingDigest = '0'.repeat(64); },
    x => { x.binding.stepIndex = 7; }, x => { x.binding.source.commit = '0'.repeat(40); },
    x => { x.binding.postcondition.visibleOppositeControl = 'Use as admin'; x.bindingDigest = digest(x.binding); },
    x => { x.binding.files.postScreenshot.sha256 = '0'.repeat(64); x.bindingDigest = digest(x.binding); },
  ]) { const p = structuredClone(proof); mutate(p); assert.throws(() => revalidateFlowEquivalenceProof(p, context)); }
  for (const c of [
    { ...context, name: 'Wrong' }, { ...context, step: { ...context.step, index: 7 } },
    { ...context, step: { ...context.step, reasons: [{ code: 'flow_changed', detail: 'changed' }] } },
    { ...context, scriptStep: { ...context.scriptStep, narration: 'stale script' } },
  ]) assert.throws(() => revalidateFlowEquivalenceProof(proof, c), /flow_equivalence_context_conflict/);
  assert.throws(() => verifyFlowEquivalenceAssets({ ...context.step, flowEquivalence: proof }), /context_required/);
  const path = join(f.root, 'flag-only.json'); writeFileSync(path, '{"verified":true}');
  assert.throws(() => loadFlowEquivalenceProof(path, context), /binding_invalid/);
});
